import Alpine from 'alpinejs';
import { defineComponent } from '~/utils';

/** The parts of the pagefind JS API we use */
type Pagefind = {
	search(term: string): Promise<{ results: { data(): Promise<PagefindResult> }[] }>;
};
type PagefindResult = {
	url: string;
	excerpt: string;
	meta: Record<string, string>;
};

/** Generated by pagefind on build, not bundled */
const pagefindUrl = '/pagefind/pagefind.js';

export default () => {
	const postsPerPage = 10;

	return defineComponent({
		term: '',
		results: [] as PagefindResult[],
		isSearching: false,
		/** Provided by the parent `Search` component */
		isOpen: false,
		init() {
			this.$watch('term', this.search.bind(this));
			Alpine.effect(async () => {
				if (!this.isOpen) return;
				await this.$nextTick();
				this.$refs.input.focus();
			});
		},
		reset() {
			this.results = [];
			this.isSearching = false;
			this.term = '';
		},
		async search(term: string) {
			if (term.trim().length < 2) {
				this.results = [];
				this.isSearching = false;
				return;
			}
			this.isSearching = true;
			const pagefind: Pagefind = await import(/* webpackIgnore: true */ pagefindUrl);
			const search = await pagefind.search(term);
			const results = await Promise.all(
				search.results.slice(0, postsPerPage).map((r) => r.data())
			);
			this.results = results;
			this.isSearching = false;
		}
	});
};
